{"task": "Find all ERROR level logs containing base64 encoded strings", "sql": "SELECT * FROM logs WHERE level = 'ERROR' AND regexp_like(message, '([A-Za-z0-9+/]{4})*([A-Za-z0-9+/]{3}=|[A-Za-z0-9+/]{2}==)')"}
{"task": "Identify service logs with potential API tokens in base64 format", "sql": "SELECT ts, service, message FROM logs WHERE regexp_like(message, '(?:[A-Za-z0-9+\\/]{4}){10,}(?:[A-Za-z0-9+\\/]{3}=|[A-Za-z0-9+\\/]{2}==)')"}
{"task": "Count base64 tokens found in each log level", "sql": "SELECT level, COUNT(*) as token_count FROM logs WHERE regexp_like(message, '[A-Za-z0-9+/]{40,}') GROUP BY level"}
{"task": "Find HTTP events that reference base64 encoded data in their path", "sql": "SELECT * FROM events WHERE regexp_like(path, '([A-Za-z0-9+\\/]{4})*([A-Za-z0-9+\\/]{3}=|[A-Za-z0-9+\\/]{2}==)')"}
{"task": "Extract logs containing JWT tokens with base64 encoding", "sql": "SELECT ts, message FROM logs WHERE regexp_like(message, '[A-Za-z0-9-_]{10,}\\.[A-Za-z0-9-_]{10,}\\.[A-Za-z0-9-_]{10,}')"}
{"task": "Search for base64 encoded passwords in log messages", "sql": "SELECT * FROM logs WHERE regexp_like(message, '(password|passwd|pwd)\\s*[:=]\\s*[A-Za-z0-9+/]{20,}')"}
{"task": "Find service logs that might contain OAuth tokens in base64 format", "sql": "SELECT ts, service, message FROM logs WHERE regexp_like(message, 'Bearer\\s+[A-Za-z0-9._\\/-]{30,}')"}
{"task": "Identify events with base64 encoded user data in paths", "sql": "SELECT * FROM events WHERE regexp_like(path, 'user_id=([A-Za-z0-9+/]{20,})')"}
{"task": "Count occurrences of base64 strings longer than 50 characters per service", "sql": "SELECT service, COUNT(*) as long_base64_count FROM logs WHERE regexp_like(message, '[A-Za-z0-9+/]{50,}') GROUP BY service"}
{"task": "Find mixed content logs that contain both base64 and JSON data", "sql": "SELECT * FROM logs WHERE regexp_like(message, '[A-Za-z0-9+/]{20,}') AND regexp_like(message, '\\{.*\\}')"}

